//! Generic adapter that bridges rig-core's `CompletionModel` trait to IronClaw's `LlmProvider`.//!//! This lets us use any rig-core provider (OpenAI, Anthropic, Ollama, etc.) as an//! `Arc<dyn LlmProvider>` without changing any of the agent, reasoning, or tool code.use crate::llm::config::CacheRetention;use async_trait::async_trait;use rig::OneOrMany;use rig::completion::{    AssistantContent, CompletionModel, CompletionRequest as RigRequest,    ToolDefinition as RigToolDefinition, Usage as RigUsage,};use rig::message::{    DocumentSourceKind, Image, ImageMediaType, Message as RigMessage, MimeType,    ToolChoice as RigToolChoice, ToolFunction, ToolResult as RigToolResult, ToolResultContent,    UserContent,};use rust_decimal::Decimal;use rust_decimal_macros::dec;use serde::Serialize;use serde::de::DeserializeOwned;use serde_json::Value as JsonValue;use std::collections::HashSet;use crate::llm::costs;use crate::llm::error::LlmError;use crate::llm::provider::{    ChatMessage, CompletionRequest, CompletionResponse, FinishReason, LlmProvider,    ToolCall as IronToolCall, ToolCompletionRequest, ToolCompletionResponse,    ToolDefinition as IronToolDefinition, strip_unsupported_completion_params,    strip_unsupported_tool_params,};/// Adapter that wraps a rig-core `CompletionModel` and implements `LlmProvider`.pub struct RigAdapter<M: CompletionModel> {    model: M,    model_name: String,    input_cost: Decimal,    output_cost: Decimal,    /// Prompt cache retention policy (Anthropic only).    /// When not `CacheRetention::None`, injects top-level `cache_control`    /// via `additional_params` for Anthropic automatic caching. Also controls    /// the cost multiplier for cache-creation tokens.    cache_retention: CacheRetention,    /// Parameter names that this provider does not support (e.g., `"temperature"`).    /// These are stripped from requests before sending to avoid 400 errors.    unsupported_params: HashSet<String>,}impl<M: CompletionModel> RigAdapter<M> {    /// Create a new adapter wrapping the given rig-core model.    pub fn new(model: M, model_name: impl Into<String>) -> Self {        let name = model_name.into();        let (input_cost, output_cost) =            costs::model_cost(&name).unwrap_or_else(costs::default_cost);        Self {            model,            model_name: name,            input_cost,            output_cost,            cache_retention: CacheRetention::None,            unsupported_params: HashSet::new(),        }    }    /// Set Anthropic prompt cache retention policy.    ///    /// Controls both cache injection and cost tracking:    /// - `None` — no caching, no surcharge (1.0×).    /// - `Short` — 5-minute TTL via `{"type": "ephemeral"}`, 1.25× write surcharge.    /// - `Long` — 1-hour TTL via `{"type": "ephemeral", "ttl": "1h"}`, 2.0× write surcharge.    ///    /// Cache injection uses Anthropic's **automatic caching** — a top-level    /// `cache_control` field in `additional_params` that gets `#[serde(flatten)]`'d    /// into the request body by rig-core.    ///    /// If the configured model does not support caching (e.g. claude-2),    /// a warning is logged once at construction and caching is disabled.    pub fn with_cache_retention(mut self, retention: CacheRetention) -> Self {        if retention != CacheRetention::None && !supports_prompt_cache(&self.model_name) {            tracing::warn!(                model = %self.model_name,                "Prompt caching requested but model does not support it; disabling"            );            self.cache_retention = CacheRetention::None;        } else {            self.cache_retention = retention;        }        self    }    /// Set the list of unsupported parameter names for this provider.    ///    /// Parameters in this set are stripped from requests before sending.    /// Supported parameter names: `"temperature"`, `"max_tokens"`, `"stop_sequences"`.    pub fn with_unsupported_params(mut self, params: Vec<String>) -> Self {        self.unsupported_params = params.into_iter().collect();        self    }    /// Strip unsupported fields from a `CompletionRequest` in place.    fn strip_unsupported_completion_params(&self, req: &mut CompletionRequest) {        strip_unsupported_completion_params(&self.unsupported_params, req);    }    /// Strip unsupported fields from a `ToolCompletionRequest` in place.    fn strip_unsupported_tool_params(&self, req: &mut ToolCompletionRequest) {        strip_unsupported_tool_params(&self.unsupported_params, req);    }}// -- Type conversion helpers --/// Normalize a JSON Schema for OpenAI strict mode compliance.////// OpenAI strict function calling requires:/// - Every object must have `"additionalProperties": false`/// - `"required"` must list ALL property keys/// - Optional fields use `"type": ["<original>", "null"]` instead of being omitted from `required`/// - Nested objects and array items are recursively normalized////// This is applied as a clone-and-transform at the provider boundary so the/// original tool definitions remain unchanged for other providers.fn normalize_schema_strict(schema: &JsonValue) -> JsonValue {    let mut schema = schema.clone();    normalize_schema_recursive(&mut schema);    schema}fn normalize_schema_recursive(schema: &mut JsonValue) {    let obj = match schema.as_object_mut() {        Some(o) => o,        None => return,    };    // Recurse into combinators: anyOf, oneOf, allOf    for key in &["anyOf", "oneOf", "allOf"] {        if let Some(JsonValue::Array(variants)) = obj.get_mut(*key) {            for variant in variants.iter_mut() {                normalize_schema_recursive(variant);            }        }    }    // Recurse into array items    if let Some(items) = obj.get_mut("items") {        normalize_schema_recursive(items);    }    // Recurse into `not`, `if`, `then`, `else`    for key in &["not", "if", "then", "else"] {        if let Some(sub) = obj.get_mut(*key) {            normalize_schema_recursive(sub);        }    }    // Only apply object-level normalization if this schema has "properties"    // (explicit object schema) or type == "object"    let is_object = obj        .get("type")        .and_then(|t| t.as_str())        .map(|t| t == "object")        .unwrap_or(false);    let has_properties = obj.contains_key("properties");    if !is_object && !has_properties {        return;    }    // Ensure "type": "object" is present    if !obj.contains_key("type") && has_properties {        obj.insert("type".to_string(), JsonValue::String("object".to_string()));    }    // Force additionalProperties: false (overwrite any existing value)    obj.insert("additionalProperties".to_string(), JsonValue::Bool(false));    // Ensure "properties" exists    if !obj.contains_key("properties") {        obj.insert(            "properties".to_string(),            JsonValue::Object(serde_json::Map::new()),        );    }    // Collect current required set    let current_required: std::collections::HashSet<String> = obj        .get("required")        .and_then(|r| r.as_array())        .map(|arr| {            arr.iter()                .filter_map(|v| v.as_str().map(String::from))                .collect()        })        .unwrap_or_default();    // Get all property keys (sorted for deterministic output)    let all_keys: Vec<String> = obj        .get("properties")        .and_then(|p| p.as_object())        .map(|props| {            let mut keys: Vec<String> = props.keys().cloned().collect();            keys.sort();            keys        })        .unwrap_or_default();    // For properties NOT in the original required list, make them nullable    if let Some(JsonValue::Object(props)) = obj.get_mut("properties") {        for key in &all_keys {            // Recurse into each property's schema FIRST (before make_nullable,            // which may change the type to an array and prevent object detection)            if let Some(prop_schema) = props.get_mut(key) {                normalize_schema_recursive(prop_schema);            }            // Then make originally-optional properties nullable            if !current_required.contains(key)                && let Some(prop_schema) = props.get_mut(key)            {                make_nullable(prop_schema);            }        }    }    // Set required to ALL property keys    let required_value: Vec<JsonValue> = all_keys.into_iter().map(JsonValue::String).collect();    obj.insert("required".to_string(), JsonValue::Array(required_value));}/// Make a property schema nullable for OpenAI strict mode.////// If it has a simple `"type": "<T>"`, converts to `"type": ["<T>", "null"]`./// If it already has an array type, adds "null" if not present./// Otherwise, wraps with `anyOf: [<existing>, {"type": "null"}]`.fn make_nullable(schema: &mut JsonValue) {    let obj = match schema.as_object_mut() {        Some(o) => o,        None => return,    };    if let Some(type_val) = obj.get("type").cloned() {        match type_val {            // "type": "string" → "type": ["string", "null"]            JsonValue::String(ref t) if t != "null" => {                obj.insert("type".to_string(), serde_json::json!([t, "null"]));            }            // "type": ["string", "integer"] → add "null" if missing            JsonValue::Array(ref arr) => {                let has_null = arr.iter().any(|v| v.as_str() == Some("null"));                if !has_null {                    let mut new_arr = arr.clone();                    new_arr.push(JsonValue::String("null".to_string()));                    obj.insert("type".to_string(), JsonValue::Array(new_arr));                }            }            _ => {}        }    } else {        // No "type" key — wrap with anyOf including null        // (handles enum-only, $ref, or combinator schemas)        let existing = JsonValue::Object(obj.clone());        obj.clear();        obj.insert(            "anyOf".to_string(),            serde_json::json!([existing, {"type": "null"}]),        );    }}/// Convert IronClaw messages to rig-core format.////// Returns `(preamble, chat_history)` where preamble is extracted from/// any System message and chat_history contains the rest.fn convert_messages(messages: &[ChatMessage]) -> (Option<String>, Vec<RigMessage>) {    let mut preamble: Option<String> = None;    let mut history = Vec::new();    for msg in messages {        match msg.role {            crate::llm::Role::System => {                // Concatenate system messages into preamble                match preamble {                    Some(ref mut p) => {                        p.push('\n');                        p.push_str(&msg.content);                    }                    None => preamble = Some(msg.content.clone()),                }            }            crate::llm::Role::User => {                if msg.content_parts.is_empty() {                    history.push(RigMessage::user(&msg.content));                } else {                    // Build multimodal user message with text + image parts                    let mut contents: Vec<UserContent> = vec![UserContent::text(&msg.content)];                    for part in &msg.content_parts {                        if let crate::llm::ContentPart::ImageUrl { image_url } = part {                            // Parse data: URL for base64 images, or use raw URL                            let image = if let Some(rest) = image_url.url.strip_prefix("data:") {                                // Format: data:<mime>;base64,<data>                                let (mime, b64) =                                    rest.split_once(";base64,").unwrap_or(("image/jpeg", rest));                                Image {                                    data: DocumentSourceKind::base64(b64),                                    media_type: ImageMediaType::from_mime_type(mime),                                    detail: None,                                    additional_params: None,                                }                            } else {                                Image {                                    data: DocumentSourceKind::url(&image_url.url),                                    media_type: None,                                    detail: None,                                    additional_params: None,                                }                            };                            contents.push(UserContent::Image(image));                        }                    }                    if let Ok(many) = OneOrMany::many(contents) {                        history.push(RigMessage::User { content: many });                    } else {                        history.push(RigMessage::user(&msg.content));                    }                }            }            crate::llm::Role::Assistant => {                if let Some(ref tool_calls) = msg.tool_calls {                    // Assistant message with tool calls                    let mut contents: Vec<AssistantContent> = Vec::new();                    if !msg.content.is_empty() {                        contents.push(AssistantContent::text(&msg.content));                    }                    for (idx, tc) in tool_calls.iter().enumerate() {                        let tool_call_id =                            normalized_tool_call_id(Some(tc.id.as_str()), history.len() + idx);                        contents.push(AssistantContent::ToolCall(                            rig::message::ToolCall::new(                                tool_call_id.clone(),                                ToolFunction::new(tc.name.clone(), tc.arguments.clone()),                            )                            .with_call_id(tool_call_id),                        ));                    }                    if let Ok(many) = OneOrMany::many(contents) {                        history.push(RigMessage::Assistant {                            id: None,                            content: many,                        });                    } else {                        // Shouldn't happen but fall back to text                        history.push(RigMessage::assistant(&msg.content));                    }                } else {                    history.push(RigMessage::assistant(&msg.content));                }            }            crate::llm::Role::Tool => {                // Tool result message: wrap as User { ToolResult }.                // Merge consecutive tool results into a single User message                // so the API sees one multi-result message instead of                // multiple consecutive User messages (which Anthropic rejects).                let tool_id = normalized_tool_call_id(msg.tool_call_id.as_deref(), history.len());                let tool_result = UserContent::ToolResult(RigToolResult {                    id: tool_id.clone(),                    call_id: Some(tool_id),                    content: OneOrMany::one(ToolResultContent::text(&msg.content)),                });                let should_merge = matches!(                    history.last(),                    Some(RigMessage::User { content }) if content.iter().all(|c| matches!(c, UserContent::ToolResult(_)))                );                if should_merge {                    if let Some(RigMessage::User { content }) = history.last_mut() {                        content.push(tool_result);                    }                } else {                    history.push(RigMessage::User {                        content: OneOrMany::one(tool_result),                    });                }            }        }    }    (preamble, history)}/// Responses-style providers require a non-empty tool call ID.fn normalized_tool_call_id(raw: Option<&str>, seed: usize) -> String {    match raw.map(str::trim).filter(|id| !id.is_empty()) {        Some(id) => id.to_string(),        None => format!("generated_tool_call_{seed}"),    }}/// Convert IronClaw tool definitions to rig-core format.////// Applies OpenAI strict-mode schema normalization to ensure all tool/// parameter schemas comply with OpenAI's function calling requirements.fn convert_tools(tools: &[IronToolDefinition]) -> Vec<RigToolDefinition> {    tools        .iter()        .map(|t| RigToolDefinition {            name: t.name.clone(),            description: t.description.clone(),            parameters: normalize_schema_strict(&t.parameters),        })        .collect()}/// Convert IronClaw tool_choice string to rig-core ToolChoice.fn convert_tool_choice(choice: Option<&str>) -> Option<RigToolChoice> {    match choice.map(|s| s.to_lowercase()).as_deref() {        Some("auto") => Some(RigToolChoice::Auto),        Some("required") => Some(RigToolChoice::Required),        Some("none") => Some(RigToolChoice::None),        _ => None,    }}/// Extract text and tool calls from a rig-core completion response.